#if UNITY_EDITOR
using System;
using System.Globalization;
using System.IO;
using System.Text;

namespace ZFrame.Data.ConfigEditor
{
    /// <summary>
    /// Pure schema -> C# source emitter (no Unity APIs, deterministic output).
    /// Emits one <see cref="ZFrame.Data.Config.ConfigRow"/>-derived class per
    /// schema: auto-generated marker, source table path and one auto-property
    /// per column (string/int/float/bool; numeric columns keep their CSV
    /// [min,max] as <c>[field: UnityEngine.Range]</c>). The first Id column is
    /// inherited from the base class and never re-emitted.
    /// </summary>
    public static class ConfigRowCodegen
    {
        /// <summary>Namespace of all generated row types (must match the hand-migrated tables).</summary>
        public const string RowNamespace = "ZFrame.Data.Config";

        /// <summary>Emits the C# source for a valid schema; throws on invalid input (callers check IsValid first).</summary>
        public static string Generate(ConfigRowSchema schema)
        {
            if (schema == null)
            {
                throw new ArgumentNullException(nameof(schema));
            }

            if (!schema.IsValid)
            {
                throw new ArgumentException(
                    "schema 非法，拒绝生成坏代码: " + string.Join("; ", schema.Errors), nameof(schema));
            }

            var sourcePath = OneLine(schema.SourceCsvPath ?? "(unknown)");
            var sb = new StringBuilder();
            sb.Append("// <auto-generated>\n");
            sb.Append("// 本文件由 ZFrame.Data.ConfigEditor.ConfigRowCodegen 从配置表 schema 自动生成，请勿手改。\n");
            sb.Append($"// 源表: {sourcePath}\n");
            sb.Append("// 重新生成: Unity 菜单 ZFrame/Config/生成行类型(全部) 或\n");
            sb.Append("//   -executeMethod ZFrame.Data.ConfigEditor.ConfigCodeGenerator.GenerateAllFromCommandLine\n");
            sb.Append("// </auto-generated>\n");
            sb.Append("using System;\n");
            sb.Append('\n');
            sb.Append($"namespace {RowNamespace}\n");
            sb.Append("{\n");
            sb.Append($"    /// <summary>Generated row type from {sourcePath}. Do not edit by hand.</summary>\n");
            sb.Append("    [Serializable]\n");
            sb.Append($"    public class {OneLine(schema.RowClassName)} : ConfigRow\n");
            sb.Append("    {\n");

            if (schema.Columns.Count == 0)
            {
                sb.Append("        // (no columns besides Id)\n");
            }

            for (int i = 0; i < schema.Columns.Count; i++)
            {
                var column = schema.Columns[i];
                if (i > 0)
                {
                    sb.Append('\n');
                }

                if (column.HasRange)
                {
                    sb.Append($"        [field: UnityEngine.Range({FormatRange(column.Type, column.RangeMin)}, "
                        + $"{FormatRange(column.Type, column.RangeMax)})]\n");
                }

                sb.Append("        [field: UnityEngine.SerializeField]\n");
                sb.Append($"        public {ConfigColumnTypeUtil.ToSchemaToken(column.Type)} {column.Name} "
                    + "{ get; set; }\n");
            }

            sb.Append("    }\n");
            sb.Append("}\n");
            return sb.ToString();
        }

        /// <summary>
        /// Writes <paramref name="content"/> to <paramref name="fullPath"/> only
        /// when it differs from the file on disk (keeps Unity churn away and is
        /// loop-safe for the import hook). UTF-8 without BOM, LF endings.
        /// </summary>
        public static bool WriteIfChanged(string fullPath, string content)
        {
            var dir = Path.GetDirectoryName(fullPath);
            if (!string.IsNullOrEmpty(dir))
            {
                Directory.CreateDirectory(dir);
            }

            if (File.Exists(fullPath))
            {
                var existing = File.ReadAllText(fullPath, new UTF8Encoding(false));
                if (existing == content)
                {
                    return false;
                }
            }

            File.WriteAllText(fullPath, content, new UTF8Encoding(false));
            return true;
        }

        private static string FormatRange(ConfigColumnType columnType, double value)
        {
            if (columnType == ConfigColumnType.Int)
            {
                return ((int)value).ToString(CultureInfo.InvariantCulture);
            }

            return FloatLiteral(value);
        }

        /// <summary>Float literal with invariant culture and f suffix (0 -> "0f", 0.5 -> "0.5f").</summary>
        private static string FloatLiteral(double value)
        {
            var text = Math.Floor(value) == value
                ? ((long)value).ToString(CultureInfo.InvariantCulture)
                : value.ToString("0.0######", CultureInfo.InvariantCulture);
            return text + "f";
        }

        /// <summary>Flattens line breaks so a weird path cannot break out of the comment block.</summary>
        private static string OneLine(string text)
        {
            return text.Replace("\r", " ").Replace("\n", " ");
        }
    }
}
#endif
